SELECT     SUM(CASE         WHEN REFERENCIA BETWEEN :VAR_DATA_INICIO AND :VAR_DATA_FIM        THEN VLRLANC ELSE 0     END) / 1000 AS VALOR_ATUAL,     SUM(CASE         WHEN REFERENCIA BETWEEN DATE_SUB(:VAR_DATA_INICIO, INTERVAL 1 YEAR) AND DATE_SUB(:VAR_DATA_FIM, INTERVAL 1 YEAR)         THEN VLRLANC ELSE 0     END) / 1000 AS VALOR_ANTERIOR FROM IMP_BASE_BALANCETE WHERE CODEMP = :VAR_EMPRESA_DRE   AND (CTACTB LIKE '3%' OR CTACTB LIKE '4%' OR CTACTB LIKE '5%')